#!/usr/bin/env python3
"""
Round 108b (culprits), 28 September 2026. Needs round 107b.

Also carries the revised 107b (threat index, V-Dem and AI rows out), which
could not apply over the first 107b. The drag note above Selected Layers,
an atlas-like relief with no white, picture layers raised with the Raise
figures as heights switch, and the active fires read from NASA again.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''
NOTE = "## Round 108b (28 September)\n\nNeeds round 107b. No tiles patch.\n\n- Carries the revised 107b, which could not apply over the first 107b: the\n  threat index (threat_*), V-Dem (vdem_*) and AI (ai_threat_*) rows are out;\n  the owner dropped those requests. The 107b note below describes the first 107b.\n- The note on dragging rows (#layer-drag-hint) sits above the Selected Layers\n  heading; Reset layers menu stays under the layers.\n- Reliefs: RELIEF_BANDS, eight stepped tints teal to cobalt, no white, darker\n  line where steps meet; RELIEF_SHADE (igor, no highlight) over the tints.\n- Picture rows rise under Raise figures as heights (RASTER_RISE, rasterRiseSet):\n  height is the share of ground the row's own picture paints, 16x16 blocks.\n- remains_fire reads GIBS's epsg4326 WMS with SRS=EPSG:3857 (the 3857 WMS does\n  not draw vector layers).\n- Script version app.js?v=999.\n\n"
HEAD = "## Round 108b (28 September)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round108b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 107b" not in text:
        sys.exit("round108b: round 107b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round108b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round108b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round108b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round 107b")
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
